package periscope

import (
	"github.com/anishathalye/periscope/internal/herror"

	"encoding/hex"
	"fmt"
	"path/filepath"
	"text/tabwriter"
)

type InfoOptions struct {
	Relative bool
}

func (ps *Periscope) Info(paths []string, options *InfoOptions) herror.Interface {
	var herr herror.Interface
	for i, p := range paths {
		if i > 0 {
			fmt.Fprintf(ps.outStream, "\n")
		}
		err := ps.info1(p, options)
		if err != nil {
			herr = err
		}
		if herr != nil && !herror.IsSilent(herr) {
			return herr
		}
	}
	return herr
}

func (ps *Periscope) info1(path string, options *InfoOptions) herror.Interface {
	absPath, _, err := ps.checkFile(path, true, false, "show", false, false)
	if err != nil {
		return err
	}
	dupeSet, herr := ps.db.Lookup(absPath)
	if herr != nil {
		return herr
	}
	nCopies := len(dupeSet)
	nDupes := 0
	if nCopies > 1 {
		nDupes = nCopies - 1
	}
	fmt.Fprintf(ps.outStream, "%s\n", path)
	w := tabwriter.NewWriter(ps.outStream, 0, 0, 0, ' ', tabwriter.DiscardEmptyColumns|tabwriter.AlignRight)
	if len(dupeSet) > 0 {
		info := dupeSet[0]
		if info.ShortHash != nil {
			fmt.Fprintf(w, "  short hash:\v %s\n", hex.EncodeToString(info.ShortHash))
		}
		if info.FullHash != nil {
			fmt.Fprintf(w, "  full hash:\v %s\n", hex.EncodeToString(info.FullHash))
		}
	}
	if nDupes > 0 {
		fmt.Fprintf(w, "  duplicates:\v %d\n", nDupes)
	}
	w.Flush()
	if nDupes > 0 {
		dirPath := filepath.Dir(absPath)
		for _, info := range dupeSet {
			if info.Path != absPath {
				showPath := info.Path
				if options.Relative {
					showPath = relPath(dirPath, info.Path)
				}
				fmt.Fprintf(ps.outStream, "    %s\n", showPath)
			}
		}
	}
	return nil
}

package periscope

import (
	"github.com/anishathalye/periscope/internal/db"
	"github.com/anishathalye/periscope/internal/herror"

	"fmt"
	"io"
	"os"
	"path/filepath"
	"strconv"
	"text/tabwriter"

	"github.com/spf13/afero"
)

type LsOptions struct {
	All       bool
	Verbose   bool
	Duplicate bool
	Unique    bool
	Relative  bool
	Recursive bool
	Files     bool
}

func (ps *Periscope) Ls(paths []string, options *LsOptions) herror.Interface {
	var herr herror.Interface
	multi := len(paths) > 1
	firstToShow := true
	for _, p := range paths {
		didShow, err := ps.ls1(p, options, multi, true, firstToShow)
		if didShow {
			firstToShow = false
		}
		if err != nil {
			herr = err
		}
		if herr != nil && !herror.IsSilent(herr) {
			return herr
		}
	}
	return herr
}

func (ps *Periscope) ls1(path string, options *LsOptions, multi, top, firstToShow bool) (bool, herror.Interface) {
	absPath, _, herr := ps.checkFile(path, false, true, "list", false, false)
	if herr != nil {
		return false, herr
	}
	files, err := afero.ReadDir(ps.fs, absPath)
	if os.IsPermission(err) {
		fmt.Fprintf(ps.errStream, "cannot access '%s': permission denied\n", path)
		return false, herror.Silent()
	}
	if err != nil {
		return false, herror.Internal(err, "")
	}
	w := tabwriter.NewWriter(ps.outStream, 0, 0, 1, ' ', tabwriter.DiscardEmptyColumns)
	var recurseDirs []string
	showAny := false
	for _, file := range files {
		if file.Name()[0] != '.' || options.All {
			didShow, isDirectory, err := ps.list1(w, file, absPath, options)
			if err != nil {
				return false, err
			}
			showAny = showAny || didShow
			if isDirectory && options.Recursive {
				recurseDirs = append(recurseDirs, file.Name())
			}
		}
	}
	withFilter := options.Duplicate || options.Unique || options.Files
	// only show directory name if any of the following are true:
	// - multiple directories are listed in the command invocation, and
	//   this is one of those directories (this is the top-level invocation)
	// - we're in recursive mode, and any of:
	//     - there are no filters
	//     - we are going to list a non-zero number of files
	echoDir := multi && top || options.Recursive && (!withFilter || showAny)
	if echoDir {
		if !firstToShow {
			fmt.Fprint(ps.outStream, "\n")
		}
		fmt.Fprintf(ps.outStream, "%s:\n", path)
	}
	w.Flush()

	didShow := echoDir || showAny
	for _, dir := range recurseDirs {
		recDidShow, err := ps.ls1(filepath.Join(path, dir), options, multi, false, firstToShow && !didShow)
		if err != nil {
			if herr == nil {
				herr = err
			}
			if !herror.IsSilent(herr) {
				return didShow, herr
			}
			continue
		}
		didShow = didShow || recDidShow
	}
	return didShow, herr
}

func (ps *Periscope) list1(out io.Writer, file os.FileInfo, dirPath string, options *LsOptions) (bool, bool, herror.Interface) {
	mode := file.Mode()
	isDirectory := false
	var desc string
	var fullPath string
	var dupeSet db.DuplicateSet
	if mode&os.ModeDir == os.ModeDir {
		desc = "d"
		isDirectory = true
	} else if mode&os.ModeSymlink == os.ModeSymlink {
		desc = "L"
	} else if mode&os.ModeNamedPipe == os.ModeNamedPipe {
		desc = "p"
	} else if mode&os.ModeSocket == os.ModeSocket {
		desc = "S"
	} else if mode&os.ModeDevice == os.ModeDevice {
		desc = "D"
	} else if mode&os.ModeCharDevice == os.ModeCharDevice {
		desc = "c"
	} else if mode.IsRegular() {
		fullPath = filepath.Join(dirPath, file.Name())
		var err herror.Interface
		dupeSet, err = ps.db.Lookup(fullPath)
		if err != nil {
			return false, false, err
		}
		nDupes := len(dupeSet) - 1
		if nDupes > 0 {
			desc = strconv.Itoa(nDupes)
		}
	} else {
		desc = "?"
	}
	show := true
	if options.Unique && len(dupeSet) > 1 {
		show = false
	}
	if options.Duplicate && len(dupeSet) < 2 {
		show = false
	}
	if options.Files && isDirectory {
		show = false
	}
	if show {
		fmt.Fprintf(out, "%s\v%s\n", desc, file.Name())
		if options.Verbose && len(dupeSet) > 1 {
			for _, info := range dupeSet {
				if info.Path != fullPath {
					showPath := info.Path
					if options.Relative {
						showPath = relPath(dirPath, info.Path)
					}
					fmt.Fprintf(out, "\v  %s\n", showPath)
				}
			}
		}
	}
	return show, isDirectory, nil
}

package periscope

import (
	"os"
	"strconv"
	"strings"
)

var scanThreads = envGetInt("PERISCOPE_SCAN_THREADS", 32)
var testDebug = envGetBool("PERISCOPE_TEST_DEBUG", false)

func envGetInt(key string, fallback int) int {
	if value, ok := os.LookupEnv(key); ok {
		if i, err := strconv.ParseInt(value, 10, 0); err == nil {
			return int(i)
		}
	}
	return fallback
}

var stringToBool map[string]bool = map[string]bool{
	"1":     true,
	"t":     true,
	"true":  true,
	"y":     true,
	"yes":   true,
	"0":     false,
	"f":     false,
	"false": false,
	"n":     false,
	"no":    false,
}

func envGetBool(key string, fallback bool) bool {
	if value, ok := os.LookupEnv(key); ok {
		if b, ok := stringToBool[strings.ToLower(value)]; ok {
			return b
		}
	}
	return fallback
}

