package periscope

import (
	"github.com/anishathalye/periscope/internal/db"
	"github.com/anishathalye/periscope/internal/herror"
	"github.com/anishathalye/periscope/internal/par"

	"fmt"
	"log"
)

type RefreshOptions struct {
}

func (ps *Periscope) Refresh(options *RefreshOptions) herror.Interface {
	summary, err := ps.db.Summary()
	if err != nil {
		return err
	}
	infos, err := ps.db.AllInfosC()
	if err != nil {
		return err
	}

	bar := ps.progressBar(int(summary.Files), `scanning: {{ counters . }} {{ bar . "[" "=" ">" " " "]" }} {{ etime . }} {{ rtime . "ETA %s" "%.0s" " " }} `)

	var gone []string
	for path := range par.MapN(infos, scanThreads, func(_, v interface{}, emit func(x interface{})) {
		path := v.(db.FileInfo).Path
		_, _, err := ps.checkFile(path, true, false, "", true, false)
		bar.Increment()
		if err != nil {
			log.Printf("removing '%s' from database", path)
			emit(path)
		}
	}) {
		gone = append(gone, path.(string))
	}
	// note: we can't actually delete the files while scanning because
	// we're doing a streaming read from the database
	tx, err := ps.db.Begin()
	if err != nil {
		return err
	}
	for _, path := range gone {
		if err = tx.Remove(path); err != nil {
			tx.Rollback()
			return err
		}
	}
	if err = tx.Commit(); err != nil {
		return err
	}
	bar.Finish()
	fmt.Fprintf(ps.outStream, "removed %d files from the database\n", len(gone))
	return nil
}

package periscope

import (
	"github.com/anishathalye/periscope/internal/db"
	"github.com/anishathalye/periscope/internal/herror"

	"container/list"
	"fmt"
	"path/filepath"
	"sync"

	"github.com/dustin/go-humanize"
)

type ReportOptions struct {
	Relative bool
}

func (ps *Periscope) Report(dir string, options *ReportOptions) herror.Interface {
	var absDir string
	if dir != "" {
		var err herror.Interface
		absDir, _, err = ps.checkFile(dir, false, true, "filter for", false, true)
		if err != nil {
			return err
		}
	}
	// We stream duplicates with AllDuplicatesC, but we don't read directly
	// from it and write results in the straightforward way. Writing to
	// output may block (e.g. if the user is using a pager), so if a user
	// had `psc report | less` open in one window and tried to `psc rm` in
	// another, they'd get a "database is locked" error. This seems like
	// it's a common enough use case that it's worth avoiding it. We
	// achieve this by buffering the results in memory.
	sets, err := ps.db.AllDuplicatesC(absDir)
	if err != nil {
		return err
	}

	buf := list.New()
	done := false
	var mu sync.Mutex
	cond := sync.NewCond(&mu)
	go func() {
		for set := range sets {
			mu.Lock()
			buf.PushBack(set)
			cond.Signal()
			mu.Unlock()
		}
		mu.Lock()
		done = true
		cond.Signal()
		mu.Unlock()
	}()

	var refDir string
	if options.Relative {
		var err error
		refDir, err = filepath.Abs(dir) // if dir == "", this will treat it like dir = "."
		if err != nil {
			return herror.Internal(err, "")
		}
	}
	first := true
	for {
		mu.Lock()
		for !done && buf.Len() == 0 {
			cond.Wait()
		}
		if done && buf.Len() == 0 {
			mu.Unlock()
			break
		}
		front := buf.Front()
		set := front.Value.(db.DuplicateSet)
		buf.Remove(front)
		mu.Unlock()

		if !first {
			fmt.Fprintf(ps.outStream, "\n")
		}
		fmt.Fprintf(ps.outStream, "%s\n", humanize.Bytes(uint64(set[0].Size))) // all files within a set have the same size
		for _, info := range set {
			path := info.Path
			if options.Relative {
				path = relPath(refDir, path)
			}
			fmt.Fprintf(ps.outStream, "  %s\n", path)
		}
		first = false
	}

	return nil
}

package periscope

import (
	"github.com/anishathalye/periscope/internal/herror"

	"bytes"
	"fmt"
	"log"
	"os"
	"strings"
)

type RmOptions struct {
	Recursive bool
	Verbose   bool
	DryRun    bool
	Contained []string
	Arbitrary bool
}

func (ps *Periscope) Rm(paths []string, options *RmOptions) herror.Interface {
	var herr herror.Interface

	// validate arguments
	var absContained []string
	for _, contained := range options.Contained {
		absPath, _, herr := ps.checkFile(contained, false, true, "access", false, true)
		if herr != nil {
			return herr
		}
		absContained = append(absContained, absPath)
	}

	for _, path := range paths {
		absPath, info, err := ps.checkFile(path, false, false, "remove", false, false)
		if err != nil {
			if !herror.IsSilent(err) {
				return err
			}
			herr = err
			continue
		}
		if info.Mode().IsRegular() {
			err = ps.removeFile(path, options, absContained)
		} else {
			err = ps.removeDirectory(path, absPath, options, absContained)
		}
		if err != nil {
			if !herror.IsSilent(err) {
				return err
			}
			herr = err
		}
	}
	return herr
}

func (ps *Periscope) removeFile(path string, options *RmOptions, absContained []string) herror.Interface {
	return ps.remove1(map[string]struct{}{path: {}}, options, true, "", absContained)
}

func (ps *Periscope) removeDirectory(path string, absPath string, options *RmOptions, absContained []string) herror.Interface {
	if !options.Recursive {
		fmt.Fprintf(ps.errStream, "cannot remove '%s': must specify -r/--recursive to delete directories\n", path)
		return herror.Silent()
	}
	c, herr := ps.db.LookupAllC(absPath, true)
	if herr != nil {
		return herr
	}
	byHash := make(map[[HashSize]byte]map[string]struct{})
	for dupInfo := range c {
		hash := hashToArray(dupInfo.FullHash)
		if byHash[hash] == nil {
			byHash[hash] = make(map[string]struct{})
		}
		byHash[hash][dupInfo.Path] = struct{}{}
	}
	for _, candidates := range byHash {
		err := ps.remove1(candidates, options, false, path, absContained)
		if err != nil {
			herr = err
		}
		if herr != nil && !herror.IsSilent(herr) {
			// interrupts execution
			return herr
		}
	}
	return herr
}

func (ps *Periscope) remove1(candidates map[string]struct{}, options *RmOptions, singleFile bool, directory string, absContained []string) herror.Interface {
	// take a conservative approach to deleting files:
	// - compute a full hash of all files in the set; if they're not all the same, abort
	// - go through all other files in the same duplicate set that are
	//   outside the candidate set (and if contained directories are specified,
	//   then only count the ones that are present in any of the contained
	//   directories); if none matches the hash, abort
	// - delete all candidates in the set

	// early sanity checks
	var path0, absPath0 string
	absPaths := make(map[string]struct{})
	infos := make(map[string]os.FileInfo)
	for path := range candidates {
		absPath, info, err := ps.checkFile(path, true, false, "remove", !singleFile, false)
		if err != nil {
			if singleFile {
				return err
			}
			continue
		}
		infos[absPath] = info
		absPaths[absPath] = struct{}{}
		path0 = path // some arbitrary path
		absPath0 = absPath
	}
	if len(infos) == 0 {
		// no candidates when deleting a directory (all files disappeared)
		return nil
	}
	// `candidates` is never used after this point
	set, _ := ps.db.Lookup(absPath0)
	// ensure all candidates contained in set
	duplicateSet := make(map[string]struct{})
	for _, info := range set {
		duplicateSet[info.Path] = struct{}{}
	}
	allContained := true
	for path := range absPaths {
		if _, ok := duplicateSet[path]; !ok {
			allContained = false
			break
		}
	}
	if !allContained {
		if singleFile {
			// use path0 to use the non-absolute path that was passed in
			fmt.Fprintf(ps.errStream, "cannot remove '%s': no duplicates\n", path0)
			return herror.Silent()
		}
		return nil
	}

	// leave out one of the candidates if no duplicates elsewhere and arbitrary option is given
	if len(duplicateSet) == len(absPaths) && options.Arbitrary {
		// arbitrarily choose a single path to avoid deleting;
		// don't choose path0/absPath0 because we use those later
		for absPath := range absPaths {
			if absPath != absPath0 {
				delete(absPaths, absPath) // this is safe to do while iterating over the map
				break
			}
		}
	}

	// the rest of this function is the most critical code in this entire
	// program: it should only delete files if there's a duplicate
	// elsewhere in the filesystem

	// compute hash of files we are deleting, and ensure that hashes of all
	// candidates match each other
	var hash []byte
	for path := range absPaths {
		currHash, err := ps.hashFile(path)
		if err != nil {
			log.Printf("hashFile('%s') returned error: %s", path, err)
			if singleFile {
				if os.IsPermission(err) {
					fmt.Fprintf(ps.errStream, "cannot remove '%s': permission denied\n", path0)
				} else {
					fmt.Fprintf(ps.errStream, "cannot remove '%s': %s\n", path0, err)
				}
				return herror.Silent()
			}
			// skip/remove the candidate but keep going
			delete(absPaths, path) // note: this is safe to do while iterating over the map
			continue
		}
		if hash == nil {
			hash = currHash
		} else {
			if !bytes.Equal(hash, currHash) {
				// files within set don't agree; give up
				return nil
			}
		}
	}

	// because we might delete paths in the above loop, check to see that
	// there are still paths to remove
	if len(absPaths) == 0 {
		return nil
	}

	// ensure that a copy exists elsewhere
	otherMatch := false
	for path := range duplicateSet {
		if _, ok := absPaths[path]; ok {
			// this is one of the paths we are considering deleting
			continue // bad candidate
		}
		if len(absContained) > 0 {
			// check if path is in any of the contained directories
			inContained := false
			for _, containedDir := range absContained {
				if strings.HasPrefix(path, containedDir+string(os.PathSeparator)) {
					inContained = true
					break
				}
			}
			if !inContained {
				// outside set we are considering deleting, but not in
				// any contained directory
				continue // bad candidate
			}
		}
		// check that the hash still matches, that the file still
		// exists and hasn't changed
		otherHash, err := ps.hashFile(path)
		if err != nil {
			log.Printf("hashFile('%s') returned error: %s", path, err.Error())
			continue // bad candidate
		}
		if bytes.Equal(hash, otherHash) {
			_, otherInfo, err := ps.checkFile(path, true, false, "", true, false)
			if err != nil {
				log.Printf("checkFile('%s') returned error: %s", path, err.Error())
				continue // bad candidate
			}
			// be extra sure that they aren't the same file
			bad := false
			if ps.realFs {
				for delPath := range absPaths {
					if os.SameFile(infos[delPath], otherInfo) {
						bad = true
						break
					}
				}
			}
			if !bad {
				otherMatch = true
				break
			}
		}
		// keep trying to find a duplicate ...
	}
	if !otherMatch {
		if singleFile {
			if len(absContained) > 0 {
				if len(absContained) == 1 {
					fmt.Fprintf(ps.errStream, "cannot remove '%s': no duplicates in '%s'\n", path0, options.Contained[0])
				} else {
					fmt.Fprintf(ps.errStream, "cannot remove '%s': no duplicates in specified contained directories\n", path0)
				}
			} else {
				fmt.Fprintf(ps.errStream, "cannot remove '%s': no duplicates\n", path0)
			}
			return herror.Silent()
		}
		return nil
	}

	// okay, we can delete all candidates in the set
	if singleFile {
		// path that is passed in, path0, is what the user typed, so we
		// use that for printing purposes
		if !options.DryRun {
			err := ps.fs.Remove(absPath0)
			if os.IsNotExist(err) {
				fmt.Fprintf(ps.errStream, "cannot remove '%s': no such file\n", path0)
				return herror.Silent()
			} else if os.IsPermission(err) {
				fmt.Fprintf(ps.errStream, "cannot remove '%s': permission denied\n", path0)
				return herror.Silent()
			} else if err != nil {
				return herror.Internal(err, "")
			}
			herr := ps.db.Remove(absPath0)
			if herr != nil {
				return herr
			}
		}
		if options.Verbose {
			fmt.Fprintf(ps.outStream, "rm %s\n", path0)
		}
	} else {
		// delete in sorted order
		for absPath := range absPaths {
			// calculate a nicer version to print to the user
			rel := relFrom(directory, absPath)
			if options.Verbose {
				fmt.Fprintf(ps.outStream, "rm %s\n", rel)
			}
			if !options.DryRun {
				err := ps.fs.Remove(absPath)
				if err != nil && !(os.IsNotExist(err) || os.IsPermission(err)) {
					log.Printf("Remove('%s') returned an error: %s", absPath, err)
				}
				if err == nil {
					herr := ps.db.Remove(absPath)
					if herr != nil {
						return herr
					}
				}
			}
		}
	}
	return nil
}

package periscope

import (
	"github.com/anishathalye/periscope/internal/db"
	"github.com/anishathalye/periscope/internal/herror"
	"github.com/anishathalye/periscope/internal/par"

	"encoding/binary"
	"log"
	"os"

	"github.com/spf13/afero"
)

type ScanOptions struct {
	Minimum int64
	Maximum int64
}

func (ps *Periscope) Scan(paths []string, options *ScanOptions) herror.Interface {
	// check that paths exist before starting any work
	absPaths := make([]string, len(paths))
	for i, path := range paths {
		abs, _, err := ps.checkFile(path, false, true, "scan", false, true)
		if err != nil {
			return err
		}
		absPaths[i] = abs
	}
	dupes, done := ps.findDuplicates(absPaths, options)
	tx, err := ps.db.Begin()
	if err != nil {
		return err
	}
	// remove previously scanned files in paths we are now searching
	for _, path := range absPaths {
		err := tx.RemoveDir(path, options.Minimum, options.Maximum)
		if err != nil {
			tx.Rollback()
			return err
		}
	}
	// add all the new things we've found
	for info := range dupes {
		err := tx.Add(info.(db.FileInfo))
		if err != nil {
			tx.Rollback()
			return err
		}
	}
	// create indexes if they don't exist already
	err = tx.CreateIndexes()
	if err != nil {
		tx.Rollback()
		return err
	}
	if err = tx.Commit(); err != nil {
		return err
	}
	done()
	return nil
}

// we use this to avoid database writes; findFilesBySize finds files in the
// directory to be scanned, and it also looks up relevant files to consider
// from the database; we want to add newly scanned files to the database
// regardless, but for infos that were already there, we only want to write to
// the database if they info has been updated (we've computed a hash that
// wasn't there before)
type searchResult struct {
	info db.FileInfo
	old  bool
}

// return value also includes the relevant stuff in the DB
//
// we do this here so that there are no db reads in the rest of findDuplicates,
// so we can do a streaming write into the db without concurrent reads
func (ps *Periscope) findFilesBySize(paths []string, options *ScanOptions) (map[int64][]searchResult, int) {
	sizeToInfos := make(map[int64][]searchResult)
	files := 0

	bar := ps.progressBar(0, `searching: {{ counters . }} files {{ etime . }} `)

	for _, root := range paths {
		err := afero.Walk(ps.fs, root, func(path string, info os.FileInfo, err error) error {
			if err != nil {
				log.Printf("%s", err)
				return nil
			}
			if !info.Mode().IsRegular() {
				return nil
			}
			size := info.Size()
			if size > options.Minimum && (options.Maximum == 0 || size <= options.Maximum) {
				if len(sizeToInfos[size]) == 0 {
					// find all relevant files from the database, skipping the
					// ones that are included in paths; we only do this once per
					// size (after we've seen a particular size, the [size] key
					// will contain at least one element, so we won't re-do this
					if known, err := ps.db.InfosBySize(size); err == nil {
						for _, k := range known {
							if !containedInAny(k.Path, paths) {
								sizeToInfos[size] = append(sizeToInfos[size], searchResult{info: k, old: true})
								files++
							}
						}
					}
				}
				sizeToInfos[size] = append(sizeToInfos[size], searchResult{
					info: db.FileInfo{
						Path:      path,
						Size:      size,
						ShortHash: nil,
						FullHash:  nil,
					},
					old: false,
				})
				files++
				bar.Increment()
			}
			return nil
		})
		if err != nil {
			log.Printf("Walk() returned error: %s", err)
		}
	}
	bar.Finish()
	return sizeToInfos, files
}

// paths consists of absolute paths with no symlinks
func (ps *Periscope) findDuplicates(searchPaths []string, options *ScanOptions) (<-chan interface{}, func()) {
	sizeToInfos, files := ps.findFilesBySize(searchPaths, options)

	bar := ps.progressBar(files, `analyzing: {{ counters . }} {{ bar . "[" "=" ">" " " "]" }} {{ etime . }} {{ rtime . "ETA %s" "%.0s" " " }} `)
	done := func() {
		bar.Finish()
	}

	return par.MapN(sizeToInfos, scanThreads, func(k, v interface{}, emit func(x interface{})) {
		size := k.(int64)
		searchResults := v.([]searchResult)

		// files may appear multiple times, if the same directory is repeated in the
		// arguments to scan; skip those
		seen := make(map[string]struct{})
		var infos []db.FileInfo
		// have we updated the data for this path (computed a new hash)? if so, we will
		// write the relevant info to the database
		var updated []bool // has infos[i] been updated?
		for _, result := range searchResults {
			path := result.info.Path
			if _, ok := seen[path]; ok {
				bar.Add(1) // no more work to do for skipped search results
				continue
			}
			seen[path] = struct{}{}
			infos = append(infos, result.info)
			if !result.old {
				updated = append(updated, true)
			} else {
				updated = append(updated, false)
			}
		}

		// if there's only one file with this size, we don't need to do any hashing
		if len(infos) == 1 {
			// the following check should always be true
			if updated[0] {
				emit(infos[0])
			}
			bar.Add(1)
			return
		}

		// compute short hashes for all files (skipping the ones where
		// we already have short hashes), bucketing results by short hash
		szBuf := make([]byte, 8)
		binary.LittleEndian.PutUint64(szBuf, uint64(size))
		byShortHash := make(map[[ShortHashSize]byte][]int) // indices into infos array
		for i := range infos {
			info := &infos[i]
			// compute short hash if necessary
			if info.ShortHash == nil {
				// key by size to have unique short hashes, so we can use them as global identifiers
				hash, err := ps.hashPartial(info.Path, szBuf)
				if err != nil {
					log.Printf("hashPartial() returned error: %s", err)
					bar.Add(1) // ignored; no more work to do for this file
					continue   // ignore this file
				}
				info.ShortHash = hash
				updated[i] = true
			}
			hashArr := shortHashToArray(info.ShortHash)
			byShortHash[hashArr] = append(byShortHash[hashArr], i)
		}

		// wherever there is > 1 file in a bucket, compute the full
		// hashes (skipping the ones where we already have full hashes)
		for _, indices := range byShortHash {
			if len(indices) <= 1 {
				// no need to compute full hash
				bar.Add(len(indices)) // no more work to do for these
				continue
			}
			// collide on short hash; hash full file
			for _, index := range indices {
				info := &infos[index]
				if info.FullHash == nil {
					hash, err := ps.hashFile(info.Path)
					if err != nil {
						log.Printf("hashFile() returned error: %s", err)
						bar.Add(1) // ignored; no more work to do for this file
						continue   // ignore this file
					}
					info.FullHash = hash
					updated[index] = true
				}
				bar.Add(1)
			}
		}

		// emit all files for which we've done some work, where there is new info to save to
		// the database
		for i, info := range infos {
			if updated[i] {
				emit(info)
			}
		}
	}), done
}

package periscope

import (
	"github.com/anishathalye/periscope/internal/herror"

	"fmt"
	"text/tabwriter"

	"github.com/dustin/go-humanize"
)

type SummaryOptions struct {
}

func (ps *Periscope) Summary(options *SummaryOptions) herror.Interface {
	summary, err := ps.db.Summary()
	if err != nil {
		return err
	}
	w := tabwriter.NewWriter(ps.outStream, 0, 0, 0, ' ', tabwriter.DiscardEmptyColumns|tabwriter.AlignRight)
	fmt.Fprintf(w, "tracked\v %s\v\n", humanize.Comma(summary.Files))
	fmt.Fprintf(w, "unique\v %s\v\n", humanize.Comma(summary.Unique))
	fmt.Fprintf(w, "duplicate\v %s\v\n", humanize.Comma(summary.Duplicate))
	fmt.Fprintf(w, "overhead\v %s\v\n", humanize.Bytes(uint64(summary.Overhead)))
	w.Flush()
	return nil
}

package periscope

import (
	"github.com/anishathalye/periscope/internal/herror"

	"fmt"
	"text/tabwriter"
)

type TreeOptions struct {
	All bool
}

func (ps *Periscope) Tree(root string, options *TreeOptions) herror.Interface {
	absRoot, _, err := ps.checkFile(root, false, true, "show", false, true)
	if err != nil {
		return err
	}
	w := tabwriter.NewWriter(ps.outStream, 0, 0, 1, ' ', tabwriter.DiscardEmptyColumns)
	r, herr := ps.db.LookupAll(absRoot, options.All)
	if herr != nil {
		return herr
	}
	for _, dupe := range r {
		_, _, err := ps.checkFile(dupe.Path, true, false, "", true, false)
		if err != nil {
			// something has changed
			continue
		}
		showPath := relPath(absRoot, dupe.Path)
		fmt.Fprintf(w, "%d\v%s\n", dupe.Count-1, showPath)
	}
	w.Flush()
	return nil
}

package testfs

import (
	"bytes"
	"encoding/binary"
	"fmt"
	"io"
	"math/rand"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"

	"github.com/spf13/afero"
)

type FileDesc struct {
	Path string
	Size int64
	Seed int64
}

type Fs struct {
	files []FileDesc
}

func New(files []FileDesc) *Fs {
	sort.Sort(byPath(files))
	return &Fs{files}
}

type byPath []FileDesc

func (a byPath) Len() int {
	return len(a)
}

func (a byPath) Swap(i, j int) {
	a[i], a[j] = a[j], a[i]
}

func (a byPath) Less(i, j int) bool {
	return a[i].Path < a[j].Path
}

func genFile(w io.Writer, size int64, seed int64) {
	if size == 0 {
		return
	}
	if size < 8 {
		panic("testfs: doesn't support 0 < size < 8")
	}
	r := rand.New(rand.NewSource(seed))
	io.CopyN(w, r, size-8)
	// we write the file size into the end of the file, so that files with common seeds have a
	// common prefix, even when they don't have the same size
	binary.Write(w, binary.LittleEndian, seed)
}

func (fs *Fs) Mkfs() afero.Fs {
	afs := afero.NewMemMapFs()
	for _, spec := range fs.files {
		afs.MkdirAll(filepath.Dir(spec.Path), 0o755)
		f, _ := afs.Create(spec.Path)
		genFile(f, spec.Size, spec.Seed)
	}
	return afs
}

func From(fs afero.Fs) *Fs {
	var files []FileDesc
	afero.Walk(fs, "/", func(path string, info os.FileInfo, err error) error {
		if info.Mode().IsRegular() {
			f, _ := fs.Open(path)
			size := info.Size()
			var seed int64
			if size >= 8 {
				f.Seek(size-8, 0)
				binary.Read(f, binary.LittleEndian, &seed)
			}
			files = append(files, FileDesc{path, size, seed})
		}
		return nil
	})
	sort.Sort(byPath(files))
	return &Fs{files}
}

func Equal(afs afero.Fs, reference *Fs) bool {
	fs := From(afs)
	return fs.Equal(reference)
}

func (fs *Fs) Equal(other *Fs) bool {
	if len(fs.files) != len(other.files) {
		return false
	}
	for i := range fs.files {
		if fs.files[i] != other.files[i] {
			return false
		}
	}
	return true
}

func ShowIndent(afs afero.Fs, n int) string {
	return From(afs).ShowIndent(n)
}

func Show(afs afero.Fs) string {
	return ShowIndent(afs, 0)
}

func (fs *Fs) ShowIndent(n int) string {
	out := new(bytes.Buffer)
	for _, file := range fs.files {
		fmt.Fprint(out, strings.Repeat(" ", n))
		fmt.Fprintf(out, "%s [%d %d]\n", file.Path, file.Size, file.Seed)
	}
	return out.String()
}

func (fs *Fs) Show() string {
	return fs.ShowIndent(0)
}

func Read(s string) *Fs {
	re := regexp.MustCompile(`(.*) \[(\d+) (\d+)\]\n`)
	var files []FileDesc
	for _, match := range re.FindAllStringSubmatch(s, -1) {
		size, _ := strconv.ParseInt(match[2], 10, 64)
		seed, _ := strconv.ParseInt(match[3], 10, 64)
		files = append(files, FileDesc{
			Path: match[1],
			Size: size,
			Seed: seed,
		})
	}
	return New(files)
}

package testfs

import (
	"bytes"
	"testing"
)

func TestMkfs(t *testing.T) {
	fs := New([]FileDesc{
		{"/a", 1024, 0},
		{"/b", 1024, 0},
		{"/c", 4096, 0},
	})
	afs := fs.Mkfs()
	info, _ := afs.Stat("/a")
	if info.Size() != 1024 {
		t.Fatal("expected /a to exist")
	}
}

func TestEqual(t *testing.T) {
	fs := New([]FileDesc{
		{"/a", 1024, 0},
		{"/b", 1024, 0},
		{"/c/d", 4096, 0},
		{"/c/e", 4096, 1},
		{"/c/f/g", 4096, 1},
	})
	afs := fs.Mkfs()
	if !Equal(afs, fs) {
		t.Fatalf("expected:\n%sgot:\n%s", fs.ShowIndent(2), ShowIndent(afs, 2))
	}
}

func TestEqualNot(t *testing.T) {
	fs1 := New([]FileDesc{
		{"/a", 1024, 0},
		{"/b", 1024, 0},
	})
	fs2 := New([]FileDesc{
		{"/b", 1024, 0},
		{"/a", 1024, 0},
		{"/c", 1024, 0},
	})
	fs3 := New([]FileDesc{
		{"/b", 1024, 0},
		{"/a", 1024, 1},
		{"/c", 1024, 0},
	})
	if fs1.Equal(fs2) {
		t.Fatal("expected fs1 != fs2")
	}
	if fs2.Equal(fs3) {
		t.Fatal("expected fs2 != fs3")
	}
}

func TestRead(t *testing.T) {
	s := `
/a [1024 0]
/b [1024 1]
/c/d [4096 2]
`
	fs := Read(s)
	expected := New([]FileDesc{
		{"/a", 1024, 0},
		{"/b", 1024, 1},
		{"/c/d", 4096, 2},
	})
	if !fs.Equal(expected) {
		t.Fatalf("expected:\n%sgot:\n%s", expected.ShowIndent(2), fs.ShowIndent(2))
	}
}

func TestShowRead(t *testing.T) {
	fs := New([]FileDesc{
		{"/a", 0, 0},
		{"/c/e", 4096, 1},
		{"/b", 1024, 0},
		{"/c/f/g", 4096, 1},
		{"/c/d", 4096, 0},
	})
	if !Read(fs.Show()).Equal(fs) {
		t.Fatalf("expected round trip show -> read to work")
	}
}

func TestDirectories(t *testing.T) {
	fs := From(Read(`
/c/d [4096 2]
/c/e/foo [100 4]
/zero [0 0]
	`).Mkfs())
	expected := New([]FileDesc{
		{"/c/d", 4096, 2},
		{"/c/e/foo", 100, 4},
		{"/zero", 0, 0},
	})
	if !fs.Equal(expected) {
		t.Fatalf("expected:\n%sgot:\n%s", expected.ShowIndent(2), fs.ShowIndent(2))
	}
}

func TestDirectoriesHidden(t *testing.T) {
	fs := From(Read(`
/c/d [4096 2]
/c/.d/foo [100 4]
	`).Mkfs())
	expected := New([]FileDesc{
		{"/c/d", 4096, 2},
		{"/c/.d/foo", 100, 4},
	})
	if !fs.Equal(expected) {
		t.Fatalf("expected:\n%sgot:\n%s", expected.ShowIndent(2), fs.ShowIndent(2))
	}
}

func TestDirectoriesDeep(t *testing.T) {
	fs := From(Read(`
/some/deeply/nested/directory/file [4096 2]
/some/deeply/nested/directory/other [100 4]
	`).Mkfs())
	expected := New([]FileDesc{
		{"/some/deeply/nested/directory/file", 4096, 2},
		{"/some/deeply/nested/directory/other", 100, 4},
	})
	if !fs.Equal(expected) {
		t.Fatalf("expected:\n%sgot:\n%s", expected.ShowIndent(2), fs.ShowIndent(2))
	}
}

func TestSameSeedCommonPrefix(t *testing.T) {
	fs := Read(`
/a [10000 1]
/b [12345 1]
	`).Mkfs()
	a, _ := fs.Open("/a")
	var aBuf bytes.Buffer
	aBuf.ReadFrom(a)
	aBytes := aBuf.Bytes()
	b, _ := fs.Open("/b")
	var bBuf bytes.Buffer
	bBuf.ReadFrom(b)
	bBytes := bBuf.Bytes()
	for i := 0; i < 9000; i++ {
		if aBytes[i] != bBytes[i] {
			t.Fatal("prefix mismatch")
		}
	}
}
